public User getUser(String id) {
    // Cache-Aside Pattern
    User user = cache.get(id);
    if (user == null) {
        user = db.findById(id);
        if (user != null) cache.put(id, user);
    }
    return user;
}

public void saveUser(User user) {
    // Write-Around Pattern
    db.save(user);
    cache.invalidate(user.getId());
}
